# # 7.5 Relating pathways to reactions through parce dataframe

# In[35]:


def parse_pathway_reactions(row):
    '''splitting parce df, a string per row with pathway ID followed by space-separated reaction IDs'''
    parts = row.split()
    pathway_id = parts[0]
    reactions = parts[1:]
    return pathway_id, reactions
parce.columns = ['raw']
parce[['pathway', 'reactions']] = parce['raw'].apply(lambda x: pd.Series(parse_pathway_reactions(x)))

# create a mapping between reaction to pathways from parce
reaction_to_pathways = defaultdict(set)

for _, row in parce.iterrows():
    pid = row['pathway']
    for rxn in row['reactions']:
        reaction_to_pathways[rxn].add(pid)

# convert sets to lists
reaction_to_pathways = {k: list(v) for k,v in reaction_to_pathways.items()}

# In[36]:


# getting reaction on a correct formate
react_ori = react_ori.rename_axis('rxn', axis='index')
react_ori = react_ori.reset_index(drop=False)
# transforming to long format
rxn_long = react_ori.melt(id_vars=['rxn'],var_name='Sites',value_name= 'rxn_abundance')
# Annotate react dataframe with pathway 
def get_pathways(rxn_id):
    return reaction_to_pathways.get(rxn_id, [])

# Create a new column with list of pathways per reaction
rxn_long['path_parce'] = rxn_long['rxn'].apply(get_pathways)


# In[37]:


# Now it would be possible to join pathway_long with rxn_long on path_parce and ipath
