rxn_long_exploded = rxn_long.explode('path_parce')
#Filter out rows where path_parce is empty or NaN
rxn_long_exploded = rxn_long_exploded[rxn_long_exploded['path_parce'].notna()]
rxn_long_exploded 
# Now merge rxn_long_exploded with pathway_long on path_parce and ipath
merged_df = rxn_long_exploded.merge(
    pathway_long,
    left_on=['path_parce', 'Sites'],
    right_on=['ipath', 'Sites'],
    how='inner'  # or 'left' to keep all reactions even if no pathway match
)
merged_df.shape

