# pwy	rxn
# 0	PWY-7498	CAFFEOYL-COA-O-METHYLTRANSFERASE-RXN RXN-8262 -RXN-15537 RXN-1104 2.1.1.88-RXN -RXN-15536 RXN-8451 RXN-8452 -RXN-13900 -RXN-15534
# 1	METHGLYUT-PWY	1.1.1.283-RXN LACTALDDEHYDROG-RXN -L-LACTDEHYDROGFMN-RXN -RXN0-4281 -RXN-8632 GLYOXI-RXN GLYOXII-RXN RXN-20917
# 
# Here is a challenge and it is to standarise identifiers for joining data from different sources. Various formates RXN-8262, 1.1.1.283-RXN, GLYOXI-RXN, EC:3.4.25.1, indicate that possible problem. As a solution a function that extracts all possible identifiers from the text and then uses a mapping or cross-reference database to standardize them is proposed here.

# In[54]:


def get_raw_rxn_list(rxn_str):
    """
    Extracts all reaction IDs from a string and returns them in a list,
    without any cleaning or modification.
    """
    # This pattern captures various reaction ID formats, including those
    # with leading hyphens, and named reactions, without stripping anything.
    pattern = r'-?RXN-?\d+|(?:\d+\.\d+\.\d+\.\d+-RXN)|[A-Z0-9-]+-RXN'
    
    # Use re.findall to get all matches.
    # The str() conversion handles potential non-string input, like NaNs.
    return re.findall(pattern, str(rxn_str), re.IGNORECASE)
# calling the function
pwy_to_rxn['rxn_list'] = pwy_to_rxn['rxn'].apply(get_raw_rxn_list)
# rename columns for clarity
pwy_to_rxn = pwy_to_rxn.rename(columns={'rxn_list': 'rxn', 'rxn': 'rxn_ori'})
# Explode so each row is a single (pwy, rxn)
pwy_to_rxn_exploded = pwy_to_rxn.explode('rxn')
# rename unmapped entries for rxn
pwy_to_rxn_exploded['rxn']= pwy_to_rxn_exploded['rxn'].fillna('no_rxn')
# Remove the original 'rxn_ori' column as it is no longer needed, for when trying the regex and silence when with raw data
pwy_to_rxn_exploded = pwy_to_rxn_exploded.drop(columns=['rxn_ori'])
# Remove duplicates
pwy_to_rxn_exploded = pwy_to_rxn_exploded.drop_duplicates()

