# ## 9.4 Flattening Database List of Dictionaries

# In[ ]:


import re, json
from itertools import chain

def _safe_join_list(lst, sep='; '):
    if not isinstance(lst, list):
        return ''
    return sep.join(str(x) for x in lst if x or x == 0)

def _flatten_one_level(lst):
    # Handles ["a","b"] and [["a","b"],["c"]]
    if not isinstance(lst, list):
        return []
    out = []
    for x in lst:
        if isinstance(x, list):
            out.extend(x)
        else:
            out.append(x)
    return out

def _sanitize_col(name: str) -> str:
    return re.sub(r'[^a-zA-Z0-9_]', '_', str(name).lower())

def targeted_flatten_ec_records(ec_records):
    """
    Flatten ec_records (list[dict]) into list[dict] with string and scalar columns.
    - Keeps your current field names.
    - Adds helper flattened columns and per-category/per-metal columns.
    """
    fixed_records = []

    for rec in ec_records or []:
        fr = dict(rec)  # shallow copy

        # 1) enzyme_names: can be list or list-of-lists
        enz = rec.get('enzyme_names', [])
        enz_flat = _flatten_one_level(enz)
        # Normalize each to string
        enz_flat = [str(e) for e in enz_flat if e or e == 0]
        # Keep original; add flattened helpers
        fr['enzyme_names_flat'] = _safe_join_list(enz_flat)
        fr['enzyme_names_count'] = len(enz_flat)
        fr['enzyme_names_first'] = enz_flat[0] if enz_flat else ''

        # 2) protein_name
        pn = rec.get('protein_name', '')
        fr['protein_name'] = '' if pn is None else str(pn).strip()

        # 3)pathways_db
        fr['pathways_db_flat'] = _safe_join_list(rec.get('pathways_db', []) or [])
        fr['pathways_db_count'] = len(rec.get('pathways_db', []) or [])

        # 4) hierarchy (list -> string)
        fr['hierarchy_flat'] = _safe_join_list(rec.get('hierarchy', []) or [])
        fr['hierarchy_count'] = len(rec.get('hierarchy', []) or [])

        # 5) ko (list -> string)
        fr['ko_flat'] = _safe_join_list(rec.get('ko', []) or [])
        fr['ko_count'] = len(rec.get('ko', []) or [])

        # 6) reactions / compounds (lists -> strings)
        fr['reactions_flat'] = _safe_join_list(rec.get('reactions', []) or [])
        fr['reactions_count'] = len(rec.get('reactions', []) or [])
        fr['compounds_flat'] = _safe_join_list(rec.get('compounds', []) or [])
        fr['compounds_count'] = len(rec.get('compounds', []) or [])

        # 7) modules: list of dicts [{'id','description'}]
        modules = rec.get('modules', []) or []
        if isinstance(modules, list):
            mod_ids = []
            mod_desc = []
            for m in modules:
                if isinstance(m, dict):
                    if 'id' in m and m['id']:
                        mod_ids.append(str(m['id']))
                    if 'description' in m and m['description']:
                        mod_desc.append(str(m['description']))
            fr['modules_ids'] = _safe_join_list(mod_ids)
            fr['modules_desc'] = _safe_join_list(mod_desc)
            fr['modules_count'] = len(mod_ids) if mod_ids else 0
        else:
            fr['modules_ids'] = ''
            fr['modules_desc'] = ''
            fr['modules_count'] = 0

        # 8) metals (BRENDA + consolidated)
        fr['metals_from_brenda_flat'] = _safe_join_list(rec.get('metals_from_brenda', []) or [])
        fr['metals_from_brenda_count'] = len(rec.get('metals_from_brenda', []) or [])
        fr['metal_mapping_from_brenda_flat'] = _safe_join_list(rec.get('metal_mapping_from_brenda', []) or [])
        fr['consolidated_metals_flat'] = _safe_join_list(rec.get('consolidated_metals', []) or [])
        fr['consolidated_metals_count'] = len(rec.get('consolidated_metals', []) or [])

        # 9) corrosion_mechanisms
        fr['corrosion_mechanisms_flat'] = _safe_join_list(rec.get('corrosion_mechanisms', []) or [])
        fr['corrosion_mechanisms_count'] = len(rec.get('corrosion_mechanisms', []) or [])

        # 10) corrosion_synergies
        fr['corrosion_synergies_flat'] = _safe_join_list(rec.get('corrosion_synergies', []) or [])
        fr['corrosion_synergies_count'] = len(rec.get('corrosion_synergies', []) or [])

        # 11) functional_categories: list of dicts [{'category': str, 'score': float}]
        fc = rec.get('functional_categories', []) or []
        fc_categories = []
        if isinstance(fc, list):
            for item in fc:
                if isinstance(item, dict) and 'category' in item:
                    cat = item['category']
                    fc_categories.append(cat)
                    # Per-category score column
                    if 'score' in item:
                        safe = _sanitize_col(cat)
                        try:
                            fr[f'func_{safe}_score'] = float(item['score'])
                        except Exception:
                            fr[f'func_{safe}_score'] = item['score']
        elif isinstance(fc, str):
            fc_categories = [fc]

        fr['functional_categories_flat'] = _safe_join_list([c for c in fc_categories if c])
        fr['functional_categories_count'] = len(fc_categories)

        # 12) metal_binding_info: dict keyed by metal symbol -> {binding_count:int, common_residues:list, common_geometries:list}
        mbi = rec.get('metal_binding_info', {}) or {}
        metal_symbols = []
        if isinstance(mbi, dict):
            for sym, data in mbi.items():
                sym_safe = _sanitize_col(sym)
                metal_symbols.append(sym)
                if isinstance(data, dict):
                    # binding_count
                    if 'binding_count' in data:
                        try:
                            fr[f'metal_{sym_safe}_binding_count'] = int(data['binding_count'])
                        except Exception:
                            fr[f'metal_{sym_safe}_binding_count'] = data['binding_count']
                    # residues
                    fr[f'metal_{sym_safe}_residues'] = _safe_join_list(data.get('common_residues', []) or [])
                    # geometries
                    fr[f'metal_{sym_safe}_geometries'] = _safe_join_list(data.get('common_geometries', []) or [])
        fr['metal_binding_metals'] = _safe_join_list(metal_symbols)
        fr['operational_environmental_factors'] = rec.get('operational_environmental_factors', [])
        fr['operational_environmental_factors_flat'] = _safe_join_list(rec.get('operational_environmental_factors', []) or [])
        fr['operational_environmental_factors_count'] = len(rec.get('operational_environmental_factors', []) or [])

        # 13) synergy details (keep originals, add safe flats)
        fr['synergy_type'] = rec.get('synergy_type', '')
        fr['synergy_description'] = rec.get('synergy_description', '')
        fr['synergy_categories_flat'] = _safe_join_list(rec.get('synergy_categories', []) or [])

        # 14) ensure numeric score fields are floats when possible
        for score_field in [
            'metal_score',
            'functional_score',
            'synergy_score',
            'overall_metal_score',
            'overall_functional_score',
            'overall_synergy_score',
            'corrosion_relevance_score',
        ]:
            if score_field in rec and rec[score_field] is not None:
                try:
                    fr[score_field] = float(rec[score_field])
                except Exception:
                    fr[score_field] = rec[score_field]

        fixed_records.append(fr)

    return fixed_records

