# pathways is a structure that came in the results of picrust2 in the form of Picrus_results df it was composed of progamatic pathways(ipath) and desciptive pathways(pathways), they were 366. However the data also have 3000 Reactions and a parsing dictionary between pathways and reactions. So the pathways obtained through this parcing (path_parce 545). Unfortunately the nature of the dbs available in this study are open access and the programatic pathways are no accesible, that is why the descriptors(pathways) were taken going forward. This pathways column, was taken as backbone and the gaps were filled up with the results from path_parce. This column then contains pathways descriptive but also programatic(pathway_primary). In order to make the allocation of the categories of this pathways for the dictionaries on global_terms.py inside pathways and functional categories, a manual allocation was imposible due to the sheer amount of data (545 names). Therefore, several codes were developed to make the distribution accurate (validation notebook in scoring_system), however the result was rudimentary. Ultimately several language models were used to allocate the columns pathways into the different dictionaries, mainly Gemini and Copilot, and ultimately human review.
# ______________________
# ### Auditor Structure 
# ______________________
# the pathway_primary was used as golden truth and it was keep with no further updating because corresponds to a granular nature of the results from picrust and inputing more data to fillup the gaps would imply diluting the good data and adding noise. The pathway_primary column was use to validate the retrieved data pathways_external by objectively measuring the agreement between the two. This helps to improve the scoring system. 

