'''def create_marker_groups(balanced_markers, top_count=500, threshold_percentile=0.75):
    """
    Create specialized marker groups based on various criteria.
    Updated to remove prevalence/specificity and create unified synergy groups.

    Parameters:
        balanced_markers: DataFrame with markers (prioritized or balanced)
        top_count: Number of top markers to include (default: 500)
        threshold_percentile: Percentile for determining high-relevance markers (default: 0.75)

    Returns:
        Dictionary of marker groups by different criteria
    """
    groups = {}

    # Check if combined_score exists, otherwise calculate it if needed
    if 'combined_score' not in balanced_markers.columns:
        print("Warning: combined_score column not found. Creating basic score.")
        # Create a basic combined score from available columns
        if 'significance_score' in balanced_markers.columns:
            balanced_markers['combined_score'] = balanced_markers['significance_score'] * 3
        else:
            balanced_markers['combined_score'] = 5.0  # Default value

    # 1. TOP MARKERS - Best overview of highest-scoring markers
    top_threshold = balanced_markers['combined_score'].quantile(threshold_percentile)
    groups['top_markers'] = balanced_markers[balanced_markers['combined_score'] >= top_threshold].head(top_count)

    # 2. SIGNIFICANCE GROUPS - Statistically significant groups (p-values based)
    if 'significance_score' in balanced_markers.columns:
        sig_threshold = balanced_markers['significance_score'].quantile(threshold_percentile)
        groups['significant_markers'] = balanced_markers[balanced_markers['significance_score'] >= sig_threshold]

    # 3. COMPONENT SCORE GROUPS
    component_score_fields = {
        'overall_metal_score': 'high_metals_relevance',
        'overall_corrosion_score': 'high_mechanism_relevance',
        'pathways_score': 'high_pathway_relevance',
        'tier_score': 'high_tier_relevance',
        'corrosion_relevance_score': 'high_corrosion_relevance'
    }

    for score_field, group_name in component_score_fields.items():
        if score_field in balanced_markers.columns and not balanced_markers[score_field].isna().all():
            threshold = balanced_markers[score_field].quantile(threshold_percentile)
            if threshold > 0:  # Only create group if threshold is meaningful
                groups[group_name] = balanced_markers[balanced_markers[score_field] >= threshold]

    # 4. MECHANISMS - One consolidated group for all mechanisms
    if 'corrosion_mechanisms' in balanced_markers.columns:
        mechanism_markers = balanced_markers[balanced_markers['corrosion_mechanisms'].notna() & 
                                           (balanced_markers['corrosion_mechanisms'] != '')]
        if len(mechanism_markers) > 0:
            groups['mechanism_all'] = mechanism_markers.sort_values('combined_score', ascending=False)

    # 5. METAL CONSOLIDATED - One group for all metals
    if 'metals_consolidated' in balanced_markers.columns:
        metal_markers = balanced_markers[balanced_markers['metals_consolidated'].notna() & 
                                       (balanced_markers['metals_consolidated'] != '')]
        if len(metal_markers) > 0:
            groups['metals_consolidated'] = metal_markers.sort_values('combined_score', ascending=False)

    # 6. PATHWAYS GROUP
    if 'pathways' in balanced_markers.columns:
        pathway_markers = balanced_markers[balanced_markers['pathways'].notna() & 
                                         (balanced_markers['pathways'] != '')]
        if len(pathway_markers) > 0:
            groups['pathways_all'] = pathway_markers.sort_values('combined_score', ascending=False)

    # 7. FUNCTIONAL CATEGORIES
    if 'functional_categories_present' in balanced_markers.columns:
        func_markers = balanced_markers[balanced_markers['functional_categories_present'].notna() & 
                                      (balanced_markers['functional_categories_present'] != '')]
        if len(func_markers) > 0:
            groups['functional_categories'] = func_markers.sort_values('combined_score', ascending=False)

    # 8. pH-DEPENDENT Fe-ORGANIC COMPLEXATION GROUPS - Based on physicochemical TOC analysis
    # At this point it is necesary to create some groups that help us to disern the different scenarios 
    # on the organic matter discussion. Three groups were considered to showcase these possibilities:
    # Biofilm, organic acids complexes and inorganic acid complexes.
    
    def create_fe_complexation_groups(row):
        """Identify Fe complexation scenarios based on physicochemical analysis"""
        has_fe = False
        inorganic_score = 0
        organic_score = 0 
        biofilm_score = 0
        
        # Check for Fe presence
        if 'metals_consolidated' in row and isinstance(row['metals_consolidated'], str):
            has_fe = any(fe_term in row['metals_consolidated'].lower() for fe_term in ['fe', 'iron'])
        
        if not has_fe:
            return 'none', 'none', 'none'
        
        # 1. Inorganic acid complexes (Most acidic, pH < 5) - Green rust-like in acidic conditions
        # Fe + CO3/SO4/Cl explaining cation deficit scenarios
        inorganic_terms = ['co3', 'carbonate', 'so4', 'sulfate', 'cl', 'chloride', 'chlorine']
        if 'metals_consolidated' in row and isinstance(row['metals_consolidated'], str):
            inorganic_score += sum(1 for term in inorganic_terms if term in row['metals_consolidated'].lower())
        if 'functional_categories_present' in row and isinstance(row['functional_categories_present'], str):
            if 'chloride' in row['functional_categories_present'].lower():
                inorganic_score += 1
        
        # 2. Organic acid complexes (Slightly acidic, pH 5-6.5) - Proxy substances approach
        # Fe + Oxalate/Acetate + humic/fulvic acids explaining anion overestimation
        organic_terms = ['oxalate', 'acetate', 'acetic', 'oxalic', 'humic', 'fulvic', 'hydroxyl', 'organic acid']
        if 'metals_consolidated' in row and isinstance(row['metals_consolidated'], str):
            organic_score += sum(1 for term in organic_terms if term in row['metals_consolidated'].lower())
        if 'functional_categories_present' in row and isinstance(row['functional_categories_present'], str):
            if 'acid_production' in row['functional_categories_present'].lower():
                organic_score += 1
        if 'organic_processes' in row and isinstance(row['organic_processes'], str):
            organic_score += sum(1 for term in organic_terms if term in row['organic_processes'].lower())
        
        # 3. Biofilm complexes (Creates own environment, pH independent)
        # EPS-mediated Fe complexation, can overlap with either acid group  
        biofilm_terms = ['biofilm', 'eps', 'polysaccharide', 'protein', 'extracellular', 'matrix', 'alginate', 'cellulose']
        if 'functional_categories_present' in row and isinstance(row['functional_categories_present'], str):
            if 'biofilm' in row['functional_categories_present'].lower():
                biofilm_score += 2  # Higher weight for direct biofilm detection
        if 'corrosion_mechanisms' in row and isinstance(row['corrosion_mechanisms'], str):
            biofilm_score += sum(1 for term in biofilm_terms if term in row['corrosion_mechanisms'].lower())
        
        # Determine group memberships
        inorganic_group = 'inorganic_acid_complexes' if inorganic_score >= 1 else 'none'
        organic_group = 'organic_acid_complexes' if organic_score >= 1 else 'none'
        biofilm_group = 'biofilm_complexes' if biofilm_score >= 1 else 'none'
        
        return inorganic_group, organic_group, biofilm_group
    
    # Apply Fe complexation analysis
    complexation_results = balanced_markers.apply(lambda row: create_fe_complexation_groups(row), axis=1)
    balanced_markers['inorganic_complex'] = complexation_results.apply(lambda x: x[0])
    balanced_markers['organic_complex'] = complexation_results.apply(lambda x: x[1])
    balanced_markers['biofilm_complex'] = complexation_results.apply(lambda x: x[2])
    
    # Create the three Fe complexation groups
    inorganic_markers = balanced_markers[balanced_markers['inorganic_complex'] == 'inorganic_acid_complexes']
    if len(inorganic_markers) > 0:
        groups['inorganic_acid_complexes'] = inorganic_markers.sort_values('combined_score', ascending=False)
    
    organic_markers = balanced_markers[balanced_markers['organic_complex'] == 'organic_acid_complexes']
    if len(organic_markers) > 0:
        groups['organic_acid_complexes'] = organic_markers.sort_values('combined_score', ascending=False)
    
    biofilm_markers = balanced_markers[balanced_markers['biofilm_complex'] == 'biofilm_complexes']
    if len(biofilm_markers) > 0:
        groups['biofilm_complexes'] = biofilm_markers.sort_values('combined_score', ascending=False)
    
    # 10. UNIFIED SYNERGY GROUP - All types of synergistic interactions 
    def calculate_synergy_score(row):
        """Calculate unified synergy score including all metal synergies from corrosion_synergies"""
        synergy_score = 0
        synergy_types = []
        
        # 1. Functional category diversity
        if 'functional_categories_present' in row and isinstance(row['functional_categories_present'], str):
            key_cats = ['iron/sulfur_redox', 'ocre', 'acid_production', 'electron transfer & redox', 'biofilm_formation']
            category_count = sum(1 for cat in key_cats if cat.lower() in row['functional_categories_present'].lower())
            if category_count >= 2:
                synergy_score += category_count * 0.5
                synergy_types.append(f"functional_diversity({category_count})")
        
        # 2. Metal synergies from corrosion_synergies (Fe-S, Cu-Fe, Ni-Fe, Mn-Fe, Cr-Fe, etc.)
        if 'metals_consolidated' in row and isinstance(row['metals_consolidated'], str):
            metals_text = row['metals_consolidated'].lower()
            # Check all synergy combinations from the corrosion_synergies
            synergy_combinations = [
                (['fe', 'iron'], ['s', 'sulfur', 'sulfate', 'sulfide'], 'fe_s'),
                (['cu', 'copper'], ['fe', 'iron'], 'cu_fe'),
                (['ni', 'nickel'], ['fe', 'iron'], 'ni_fe'), 
                (['mn', 'manganese'], ['fe', 'iron'], 'mn_fe'),
                (['cr', 'chromium'], ['fe', 'iron'], 'cr_fe'),
                (['zn', 'zinc'], ['fe', 'iron'], 'zn_fe'),
                (['al', 'aluminum'], ['cu', 'copper'], 'al_cu')
            ]
            
            for metal1_terms, metal2_terms, synergy_name in synergy_combinations:
                has_metal1 = any(term in metals_text for term in metal1_terms)
                has_metal2 = any(term in metals_text for term in metal2_terms)
                if has_metal1 and has_metal2:
                    synergy_score += 1.0
                    synergy_types.append(synergy_name)
        
        # 3. Metal-organic synergy (general)
        has_metals = 'metals_consolidated' in row and isinstance(row['metals_consolidated'], str) and row['metals_consolidated'] != ''
        has_organics = 'organic_processes' in row and isinstance(row['organic_processes'], str) and row['organic_processes'] != ''
        if has_metals and has_organics:
            synergy_score += 0.8
            synergy_types.append("metal_organic")
        
        return synergy_score, "; ".join(synergy_types)
    
    # Calculate and create unified synergy group
    synergy_results = balanced_markers.apply(lambda row: calculate_synergy_score(row), axis=1)
    balanced_markers['synergy_score'] = synergy_results.apply(lambda x: x[0])
    balanced_markers['synergy_types'] = synergy_results.apply(lambda x: x[1])
    
    synergy_threshold = 1.0
    synergy_markers = balanced_markers[balanced_markers['synergy_score'] >= synergy_threshold]
    if len(synergy_markers) > 0:
        groups['unified_synergy'] = synergy_markers.sort_values(['synergy_score', 'combined_score'], ascending=False)
    
    # 11. HIGH BIOLOGICAL RELEVANCE - Interesting combined group 
    try:
        # Create a combined biological relevance score
        bio_score = np.zeros(len(balanced_markers))
        bio_cols = ['overall_corrosion_score', 'pathways_score', 'overall_functional_score'
                    ]
        
        # Add weights for each biological component
        for col in bio_cols:
            if col in balanced_markers.columns:
                # Safely convert to numeric, replacing non-numeric with 0
                bio_score += pd.to_numeric(balanced_markers[col], errors='coerce').fillna(0)
        
        # Only create group if we have meaningful biological scores
        if bio_score.sum() > 0:
            bio_threshold = np.percentile(bio_score[bio_score > 0], threshold_percentile * 100)
            groups['high_biological_relevance'] = balanced_markers[bio_score >= bio_threshold]
    except Exception as e:
        print(f"Warning: Could not create biological relevance group: {e}")

    # 11. CRITICAL CORROSION MARKERS - High-impact markers for HVAC systems
    try:
        corrosion_critical = balanced_markers[
            (balanced_markers['combined_score'] >= balanced_markers['combined_score'].quantile(0.9))
        ]
        
        # Add metal filter if column exists (focus on Fe, Mn, S for HVAC)
        if 'metals_consolidated' in balanced_markers.columns:
            corrosion_critical = corrosion_critical[
                corrosion_critical['consolidated_metals'].fillna('').str.contains('Fe|iron|Mn|manganese|S|sulfur', case=False)
            ]
        
        # Add functional categories filter if column exists
        if 'functional_categories_present' in balanced_markers.columns:
            corrosion_critical = corrosion_critical[
                corrosion_critical['functional_categories_present'].fillna('').str.contains(
                    'iron/sulfur_redox|ocre|acid_production|electron transfer|biofilm', case=False)
            ]
        # Otherwise try corrosion_mechanisms if available
        elif 'corrosion_mechanisms' in balanced_markers.columns:
            corrosion_critical = corrosion_critical[
                corrosion_critical['corrosion_mechanisms'].fillna('').str.contains(
                    'iron|sulfur|acid|electron|biofilm', case=False)
            ]
            
        if len(corrosion_critical) > 0:
            groups['corrosion_critical'] = corrosion_critical.sort_values('combined_score', ascending=False)
    except Exception as e:
        print(f"Warning: Could not create corrosion_critical group: {e}")

    # Add information about group sizes
    group_sizes = {name: len(df) for name, df in groups.items()}
    print("Marker groups created:")
    for name, size in sorted(group_sizes.items(), key=lambda x: x[1], reverse=True):
        print(f"  - {name}: {size} markers")
    
    # Print Fe complexation analysis summary
    complexation_groups = ['inorganic_acid_complexes', 'organic_acid_complexes', 'biofilm_complexes']
    present_complexation = [g for g in complexation_groups if g in groups]
    
    if present_complexation:
        print(f"\nFe Complexation Analysis (based on physicochemical TOC study):")
        for group_name in present_complexation:
            group_df = groups[group_name]
            print(f"  - {group_name}: {len(group_df)} markers")
            
        # Check for overlaps (biofilm can overlap with acid groups)
        if 'biofilm_complexes' in groups and len(present_complexation) > 1:
            biofilm_ids = set(groups['biofilm_complexes'].index)
            for acid_group in ['inorganic_acid_complexes', 'organic_acid_complexes']:
                if acid_group in groups:
                    acid_ids = set(groups[acid_group].index)
                    overlap = len(biofilm_ids.intersection(acid_ids))
                    if overlap > 0:
                        print(f"    * Biofilm-{acid_group.replace('_complexes', '')} overlap: {overlap} markers")

    # Define the score columns to be dropped from each group
    score_columns_to_drop = [
        'overall_metal_score', 'corrosion_relevance_score', 'overall_functional_score',
         'overall_synergy_score', 'overall_corrosion_score',
         'tier_score', 'hierarchy_score', 'corrosion_score_scaled', 'corrosion_cat_score',
           'corrosion_final_score',
        'metal_scores', 'significance_score',  'synergy_score'  # Keep synergy_types for analysis
    ]
    
    # Drop score columns from each group
    for group_name, group_df in groups.items():
        # Only drop columns that exist in the DataFrame
        columns_to_drop = [col for col in score_columns_to_drop if col in group_df.columns]
        if columns_to_drop:
            groups[group_name] = group_df.drop(columns=columns_to_drop)
    
    return groups'''

# ## 10.8. Generating Marker Report
# The generate_streamlined_report function transforms complex analytical results into an accessible, multi-sheet report that highlights the most relevant protein-genus pairs associated with corrosion processes. The function extracts prioritized markers (using balanced markers if available) and organizes them into four specialized sheets:
# 
# Top Corrosion Markers: A focused presentation of the highest-scoring markers with core information including genus, protein name, enzyme details, corrosion mechanisms, metal involvement, and pattern characteristics.
# Visualization Data: A streamlined dataset optimized for creating abundance pattern visualizations across risk categories.
# Detailed Scores: A comprehensive breakdown of scoring components (prevalence, specificity, frequency, pathway relevance, etc.) to provide transparency into the prioritization process.
# Mechanisms Focus: An expanded view that separates multi-mechanism proteins into individual entries, facilitating mechanism-specific analysis.
# 
# The function also generates a summary sheet with metadata about the analysis, including total markers analyzed, balancing status, and pattern distribution. When provided with an output path, the report is saved as an Excel file with appropriately formatted column names for improved readability. This structured reporting approach enables researchers to quickly identify the most promising corrosion biomarkers while maintaining access to the underlying analytical details.

# In[ ]:


def consolidate_analysis_results(analysis_results, marker_groups):
    """
    Consolidate all analysis results and marker groups into a single dictionary
    for easy parquet storage.

    Parameters:   analysis_results: Dictionary containing analysis dataframes
                  marker_groups: Dictionary containing marker groups
    Returns:      consolidated_results: Dictionary with all dataframes in one place
    """
    # Create a new consolidated dictionary
    consolidated_results = {}

    # Add main analysis dataframes
    key_dataframes = [
        'pattern_data',
        'integrated_results',
        'classified_results',
        'increasing_markers',
        'inverse_markers',
        'prioritized_markers',
        'balanced_markers'
    ]

    for key in key_dataframes:
        if key in analysis_results and analysis_results[key] is not None:
            consolidated_results[key] = analysis_results[key]
            print(f"Added {key}: {len(analysis_results[key])} rows")

    # Add marker groups
    for group_name, group_df in marker_groups.items():
        consolidated_results[f'group_{group_name}'] = group_df
        print(f"Added group_{group_name}: {len(group_df)} rows")

    print(f"Successfully consolidated {len(consolidated_results)} dataframes")
    return consolidated_results

